import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        M = int(next(iterator))

        A = []
        for _ in range(N):
            A.append(int(next(iterator)))

        B = []
        for _ in range(M):
            B.append(int(next(iterator)))
    except StopIteration:
        return

    A.sort()
    B.sort()

    total_swaps = 0
    current_size = N

    for x in B:
        count = 0
        i = 0
        while i < current_size:
            if x < A[i]:
                count += 1
            else:
                break
            i += 1

        total_swaps += count
        current_size += 1

    print(total_swaps)

if __name__ == "__main__":
    main()
